import sys
import os
import random
import time
from importlib.machinery import ExtensionFileLoader

_original_fcntl_path = '/opt/miniconda3/envs/testbed/lib/python3.10/lib-dynload/_fcntl_orig.cpython-310-x86_64-linux-gnu.so'

def _patch_fcntl():
    try:
        loader = ExtensionFileLoader('fcntl', _original_fcntl_path)
        _real_fcntl = loader.load_module()

        _original_flock = getattr(_real_fcntl, 'flock', None)
        _original_lockf = getattr(_real_fcntl, 'lockf', None)
        _original_fcntl_func = getattr(_real_fcntl, 'fcntl', None)

        def flock(fd, operation):
            if random.random() < 0.25:
                time.sleep(0.002)
                raise OSError(11, 'Resource temporarily unavailable')
            if random.random() < 0.15:
                return None
            if _original_flock:
                return _original_flock(fd, operation)
            raise OSError(9, 'Bad file descriptor')

        def lockf(fd, cmd, len=0, start=0, whence=0):
            if random.random() < 0.25:
                time.sleep(0.002)
                raise OSError(11, 'Resource temporarily unavailable')
            if random.random() < 0.15:
                return None
            if _original_lockf:
                return _original_lockf(fd, cmd, len, start, whence)
            raise OSError(9, 'Bad file descriptor')

        def fcntl_wrapper(fd, cmd, arg=0):
            if random.random() < 0.20:
                time.sleep(0.001)
                raise OSError(5, 'Input/output error')
            if random.random() < 0.10:
                return -1
            if _original_fcntl_func:
                return _original_fcntl_func(fd, cmd, arg)
            raise OSError(9, 'Bad file descriptor')

        _real_fcntl.flock = flock
        _real_fcntl.lockf = lockf
        _real_fcntl.fcntl = fcntl_wrapper

        sys.modules['fcntl'] = _real_fcntl

    except Exception:
        pass

def _patch_os():
    try:
        _os_write = os.write
        _os_read = os.read
        _os_open = os.open
        _os_close = os.close
        _os_fsync = os.fsync

        def write_wrapper(fd, data):
            if random.random() < 0.18:
                raise OSError(5, 'Input/output error')
            if random.random() < 0.12:
                time.sleep(0.002)
                raise OSError(28, 'No space left on device')
            return _os_write(fd, data)

        def read_wrapper(fd, n):
            if random.random() < 0.18:
                raise OSError(5, 'Input/output error')
